parameters.value:
={{ (() => {
    const isPage = $('Set Page Number').isExecuted;
    const isChangeVoice = $('Set Change-Voice Page Number').isExecuted;
    const isSample = $('Set Sample Voice Number').isExecuted;
    const isNormalKnit = !isPage && !isChangeVoice && !isSample;
    const isChangeVoiceKnit = isChangeVoice && $('Set Change-Voice Page Number').item.json.isKnit;
    const isKnitRender = isNormalKnit || isChangeVoiceKnit;
    const docPrefix = $('Set Doc Prefix').isExecuted ? $('Set Doc Prefix').item.json.docPrefix : (isSample ? ($('Populate Variables').item.json.sampleFolderName + '/') : ($('Set Document Folder').item.json.docFolder + '/'));
    const left = isNormalKnit ? $('Page Knitting Configuration').item.json['⬅️ Left Page Number'] : null;
    const right = isNormalKnit ? $('Page Knitting Configuration').item.json['Right Page Number ➡️'] : null;
    const p = isNormalKnit
      ? `${left}-${right}_knit`
      : (isPage
          ? $('Set Page Number').item.json.pageNumber
          : (isChangeVoice
              ? $('Set Change-Voice Page Number').item.json.fileBasename
              : 'sample_' + $('Set Sample Voice Number').item.json.voiceId
            )
        );
    const img = `temp/${docPrefix}${p}_image.png`;
    const name = isSample ? $('Set Sample Voice Number').item.json.friendlyName : null;
    const video = $('Store Video Encoding Configuration').item.json;
    const deviceArgs = video.ffmpegHardwareDeviceArgs ? video.ffmpegHardwareDeviceArgs + ' ' : '';

    const sampleImageCmds = isSample ? [
      'REFW=1920',
      'REFH=1080',
      'FONTSIZE=$((REFH / 12))',
      `NAME='${name}'`,
      'NAMELEN=${#NAME}',
      'CELLW=$(( (NAMELEN * FONTSIZE * 6 / 10) + FONTSIZE ))',
      'CELLH=$(( FONTSIZE * 2 ))',
      'COLS=$(( (REFW + CELLW - 1) / CELLW ))',
      'ROWS=$(( (REFH + CELLH - 1) / CELLH ))',
      'GRIDW=$((COLS * CELLW))',
      'OFFSETX=$(( (REFW - GRIDW) / 2 ))',
      'FILTERS=""',
      `for ((r=0; r<ROWS; r++)); do for ((c=0; c<COLS; c++)); do CELLX=$((OFFSETX + c*CELLW)); CELLY=$((r*CELLH)); FILTERS="\${FILTERS}drawtext=text='\${NAME}':fontcolor=black:fontsize=\${FONTSIZE}:x=\${CELLX}+(\${CELLW}-text_w)/2:y=\${CELLY}+(\${CELLH}-text_h)/2,"; done; done`,
      'FILTERS="${FILTERS%,}"',
      `ffmpeg -y -f lavfi -i color=white:s=\${REFW}x\${REFH} -vf "$FILTERS" -frames:v 1 ${img}`
    ] : [];

    const ffmpegCmd = isKnitRender
      ? `ffmpeg -y ${deviceArgs}-loop 1 -t "$DUR" -i ${img} -i temp/${docPrefix}${p}_audio.wav -vf "scale=trunc(iw/2)*2:trunc(ih/2)*2${video.ffmpegVideoFilterSuffix}" ${video.ffmpegVideoEncoderArgs} -c:a aac -b:a 192k temp/${docPrefix}${p}_clip.mp4`
      : `ffmpeg -y ${deviceArgs}-loop 1 -t "$DUR" -i ${img} -i temp/${docPrefix}${p}_audio.wav -filter_complex "[0:v]split[bg_src][fg_src];[bg_src]scale=iw*2:trunc(ih/2)*2,boxblur=20:3[bg];[fg_src]scale=trunc(iw/2)*2:trunc(ih/2)*2[fg];[bg][fg]overlay=(main_w-overlay_w)/2:0${video.ffmpegVideoFilterSuffix}[v]" -map "[v]" -map 1:a ${video.ffmpegVideoEncoderArgs} -c:a aac -b:a 192k temp/${docPrefix}${p}_clip.mp4`;

    return [
      'set -e',
      `export PATH=${$('Populate Variables').item.json.ffmpegPath}:$PATH`,
      ...sampleImageCmds,
      `DUR=$(ffprobe -v quiet -show_entries format=duration -of csv=p=0 temp/${docPrefix}${p}_audio.wav)`,
      ffmpegCmd,
      `(xattr -d com.apple.quarantine temp/${docPrefix}${p}_clip.mp4 2>/dev/null || true)`
    ].join(' && ');
  })() }}

={{ (() => {
    const basename = $('Determine Output Basename').item.json.outputBasename;
    const clipGlob = $('Determine Output Basename').item.json.tempClipGlob;
    const chaptersFile = $('Determine Output Basename').item.json.chaptersFile;
    const simple = $('Determine Output Basename').item.json.useSimpleConcat;
    const docPrefix = simple ? 'sample/' : ($('Set Document Folder').item.json.docFolder + '/');
    const tempDir = $('Populate Variables').item.json.tempDirRelative;
    const outputDir = $('Populate Variables').item.json.outputDirRelative;
    const video = $('Store Video Encoding Configuration').item.json;
    const deviceArgs = video.ffmpegHardwareDeviceArgs ? video.ffmpegHardwareDeviceArgs + ' ' : '';

    const sortedVoiceIds = $('Aggregate All Timestamps').item.json.pages
      .map(x => x.data)
      .filter(d => d.voiceId)
      .sort((a, b) => (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0)))
      .map(d => d.voiceId);

    const winningClipLines = (() => {
      const allPages = $('Aggregate All Timestamps').item.json.pages.map(p => p.data);
      const byRecency = allPages.slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      const claimedIndexes = new Set();
      const winners = [];
      for (const page of byRecency) {
        const coveredIndexes = page.knitPages ? page.knitPages.map(Number) : [Number(page.pageIndex)];
        if (coveredIndexes.some(index => claimedIndexes.has(index))) continue;
        coveredIndexes.forEach(index => claimedIndexes.add(index));
        winners.push(page);
      }
      winners.sort((a, b) => Math.min(...(a.knitPages ? a.knitPages.map(Number) : [a.pageIndex])) - Math.min(...(b.knitPages ? b.knitPages.map(Number) : [b.pageIndex])));
      return winners.map(page => {
        const base = page.knitPages ? page.knitPages.join('-') + '_knit' : String(page.pageIndex);
        return `echo "file '$PWD/${tempDir}/${docPrefix}${base}_clip.mp4'" >> ${tempDir}/${docPrefix}${basename}_concat_list.txt`;
      }).join(' && ');
    })();

    const concatListCheck = `[ -s ${tempDir}/${docPrefix}${basename}_concat_list.txt ] || { echo "ERROR: concat list ${tempDir}/${docPrefix}${basename}_concat_list.txt is empty, no clips matched" >&2; exit 1; }`;

    const simpleCmds = [
      `mkdir -p ${outputDir}`,
      `: > ${tempDir}/${docPrefix}${basename}_concat_list.txt`,
      ...sortedVoiceIds.map(id => `echo "file '$PWD/${tempDir}/${docPrefix}sample_${id}_clip.mp4'" >> ${tempDir}/${docPrefix}${basename}_concat_list.txt`),
      concatListCheck,
      `ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -c copy -f mp4 ${outputDir}/${docPrefix}${basename}.mp4.tmp`,
      `mv ${outputDir}/${docPrefix}${basename}.mp4.tmp ${outputDir}/${docPrefix}${basename}.mp4`,
      `(xattr -d com.apple.quarantine "$PWD/${outputDir}/${docPrefix}${basename}.mp4" 2>/dev/null || true)`
    ];

    const complexCmds = [
      `mkdir -p ${tempDir}/${docPrefix} ${outputDir}/${docPrefix}`,
      `: > ${tempDir}/${docPrefix}${basename}_concat_list.txt && ${winningClipLines}`,
      concatListCheck,
      'MAX_W=0',
      `for f in ${tempDir}/${docPrefix}*_knit_clip.mp4; do [ -f "$f" ] || break; W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$f" | head -1); if [ "$W" -gt "$MAX_W" ]; then MAX_W=$W; fi; done`,
      `SINGLE=$(find ${tempDir}/${docPrefix} -maxdepth 1 -name "${clipGlob}" ! -name "*_knit_clip.mp4" | sort -V | head -1)`,
      'if [ -n "$SINGLE" ]; then CLIP_W=$(ffprobe -v quiet -show_entries stream=width -of csv=p=0 "$SINGLE" | head -1); PAGE_W=$((CLIP_W/2)); if [ "$PAGE_W" -gt "$MAX_W" ]; then MAX_W=$PAGE_W; fi; else CLIP_W=$MAX_W; fi',
      'TARGET_W=$MAX_W',
      `if [ "$CLIP_W" -eq "$TARGET_W" ]; then ffmpeg -y -f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -c copy -f mp4 ${outputDir}/${docPrefix}${basename}.mp4.tmp; elif [ "$CLIP_W" -gt "$TARGET_W" ]; then X=$(( (CLIP_W - TARGET_W) / 2 )) && ffmpeg -y ${deviceArgs}-f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -vf "crop=\${TARGET_W}:ih:\${X}:0${video.ffmpegVideoFilterSuffix}" ${video.ffmpegFinalVideoEncoderArgs} -c:a copy -f mp4 ${outputDir}/${docPrefix}${basename}.mp4.tmp; else OX=$(( (TARGET_W - CLIP_W) / 2 )) && ffmpeg -y ${deviceArgs}-f concat -safe 0 -i ${tempDir}/${docPrefix}${basename}_concat_list.txt -i ${tempDir}/${docPrefix}${chaptersFile} -map_metadata 1 -vf "split[bg][fg];[bg]scale=\${TARGET_W}:ih,boxblur=20:3[bg_b];[fg][bg_b]overlay=\${OX}:0${video.ffmpegVideoFilterSuffix}" ${video.ffmpegFinalVideoEncoderArgs} -c:a copy -f mp4 ${outputDir}/${docPrefix}${basename}.mp4.tmp; fi`,
      `mv ${outputDir}/${docPrefix}${basename}.mp4.tmp ${outputDir}/${docPrefix}${basename}.mp4`,
      `(xattr -d com.apple.quarantine "$PWD/${outputDir}/${docPrefix}${basename}.mp4" 2>/dev/null || true)`
    ];

    return ['set -e', `export PATH=${$('Populate Variables').item.json.ffmpegPath}:$PATH`, ...(simple ? simpleCmds : complexCmds)].join(' && ');
  })() }}

