={{ (() => {
      function formatSrtTimestamp(seconds) {
        seconds = Math.max(0, seconds);
        const hours = String(Math.floor(seconds / 3600)).padStart(2, '0');
        const minutes = String(Math.floor((seconds % 3600) / 60)).padStart(2, '0');
        const secs = String(Math.floor(seconds % 60)).padStart(2, '0');
        const ms = String(Math.round((seconds % 1) * 1000)).padStart(3, '0');
        return hours + ':' + minutes + ':' + secs + ',' + ms;
      }

      function stripNonAlphanumeric(word) {
        return word.toLowerCase().replace(/[^a-z0-9]/g, '');
      }

      function buildNormalizedWordList(wordMap) {
        const normList = [];
        for (let origIdx = 0; origIdx < wordMap.length; origIdx++) {
          const normalizedTokens = wordMap[origIdx].normalized.toLowerCase().match(/[a-z0-9]+(?:'[a-z0-9]+)*/g) || [];
          for (const token of normalizedTokens) normList.push({ word: token, origIdx });
        }
        return normList;
      }

      function alignTimestampsToOriginalWords(timestamps, normList) {
        let cursor = 0;
        let lastOrigIdx = 0;

        return timestamps.map((timestamp, timestampIdx) => {
          const spokenWord = stripNonAlphanumeric(timestamp.word);
          const searchEnd = Math.min(cursor + 8, normList.length);
          let bestPosition = -1;
          let bestScore = -Infinity;

          for (let position = cursor; position < searchEnd; position++) {
            if (stripNonAlphanumeric(normList[position].word) !== spokenWord) continue;

            let score = -(position - cursor) * 2;
            for (let lookahead = 1; lookahead <= 3; lookahead++) {
              const nextTimestamp = timestamps[timestampIdx + lookahead];
              const nextNormalized = normList[position + lookahead];
              if (!nextTimestamp || !nextNormalized) break;
              if (stripNonAlphanumeric(nextTimestamp.word) === stripNonAlphanumeric(nextNormalized.word)) score += 4 - lookahead;
            }

            if (score > bestScore) {
              bestScore = score;
              bestPosition = position;
            }
          }

          const matchedPosition = bestPosition >= 0 ? bestPosition : Math.min(cursor, normList.length - 1);
          if (bestPosition >= 0) {
            cursor = Math.min(normList.length, matchedPosition + 1);
          }
          lastOrigIdx = Math.max(lastOrigIdx, normList[matchedPosition].origIdx);
          return lastOrigIdx;
        });
      }

      function buildSubtitleChunksForPage(page, timeOffset, startIdx) {
        const timestamps = page.timestamps.filter(t => /\w/.test(t.word));
        const pageDuration = page.audioDuration ?? page.timestamps[page.timestamps.length - 1].end_time;
        const originalWords = page.wordMap.map(w => w.original);
        const normList = buildNormalizedWordList(page.wordMap);
        const alignedOrigIdx = alignTimestampsToOriginalWords(timestamps, normList);

        const chunks = [];
        let timestampIdx = 0;
        let chunkIdx = startIdx;

        while (timestampIdx < timestamps.length) {
          const chunkStartTimestampIdx = timestampIdx;
          const startOrigIdx = alignedOrigIdx[chunkStartTimestampIdx];
          const targetEnd = timestamps[chunkStartTimestampIdx].start_time + 4;

          timestampIdx++;
          while (
            timestampIdx < timestamps.length &&
            (
              timestamps[timestampIdx].start_time < targetEnd ||
              alignedOrigIdx[timestampIdx] === alignedOrigIdx[timestampIdx - 1]
            )
          ) {
            timestampIdx++;
          }

          const isLastChunk = timestampIdx >= timestamps.length;
          const nextOrigIdx = isLastChunk ? originalWords.length : alignedOrigIdx[timestampIdx];
          const endOrigIdx = Math.max(startOrigIdx, nextOrigIdx - 1);

          chunks.push({
            idx: chunkIdx,
            start: formatSrtTimestamp(timestamps[chunkStartTimestampIdx].start_time + timeOffset),
            end: formatSrtTimestamp((isLastChunk ? pageDuration : timestamps[timestampIdx].start_time) + timeOffset),
            text: originalWords.slice(startOrigIdx, endOrigIdx + 1).join(' ')
          });
          chunkIdx++;
        }

        return { chunks, pageDuration };
      }

      const allPages = $('Aggregate All Timestamps').item.json.pages.map(p => p.data);
      const sampleOrdered = allPages.every(p => p.voiceId) ? allPages.slice().sort((a, b) => (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0))) : null;
      const pages = sampleOrdered || (() => {
        const byRecency = allPages.slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
        const claimedIndexes = new Set();
        const winners = [];
        for (const page of byRecency) {
          const coveredIndexes = page.knitPages ? page.knitPages.map(Number) : [Number(page.pageIndex)];
          if (coveredIndexes.some(index => claimedIndexes.has(index))) continue;
          coveredIndexes.forEach(index => claimedIndexes.add(index));
          winners.push(page);
        }
        return winners.sort((a, b) => Math.min(...(a.knitPages ? a.knitPages.map(Number) : [a.pageIndex])) - Math.min(...(b.knitPages ? b.knitPages.map(Number) : [b.pageIndex])));
      })();
      const allChunks = [];
      let timeOffset = 0, chunkIdx = 1;
      for (const page of pages) {
        const { chunks, pageDuration } = buildSubtitleChunksForPage(page, timeOffset, chunkIdx);
        allChunks.push(...chunks);
        chunkIdx += chunks.length;
        timeOffset += pageDuration;
      }
      return allChunks;
    })() }}

={{ (() => {
      const allPages = $('Aggregate All Timestamps').item.json.pages.map(p => p.data);
      const sampleOrdered = allPages.every(p => p.voiceId) ? allPages.slice().sort((a, b) => (a.voiceId < b.voiceId ? -1 : (a.voiceId > b.voiceId ? 1 : 0))) : null;
      const pages = sampleOrdered || (() => {
        const byRecency = allPages.slice().sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
        const claimedIndexes = new Set();
        const winners = [];
        for (const page of byRecency) {
          const coveredIndexes = page.knitPages ? page.knitPages.map(Number) : [Number(page.pageIndex)];
          if (coveredIndexes.some(index => claimedIndexes.has(index))) continue;
          coveredIndexes.forEach(index => claimedIndexes.add(index));
          winners.push(page);
        }
        return winners.sort((a, b) => Math.min(...(a.knitPages ? a.knitPages.map(Number) : [a.pageIndex])) - Math.min(...(b.knitPages ? b.knitPages.map(Number) : [b.pageIndex])));
      })();

      let meta = ';FFMETADATA1\n', offset = 0;

      for (const page of pages) {
        const dur = page.audioDuration ?? page.timestamps[page.timestamps.length - 1].end_time;
        const title = page.voiceLabel ? page.voiceLabel : (page.knitPages ? `Pages ${page.knitPages[0]} & ${page.knitPages[1]}` : `Page ${page.pageIndex}`);
        meta += `\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=${Math.round(offset * 1000)}\nEND=${Math.round((offset + dur) * 1000)}\ntitle=${title}\n`;
        offset += dur;
      }

      return meta;
    })() }}

={{ (() => {
    const chunks = $json.subtitleChunks;
    let srt = '';
    for (const c of chunks) {
      const words = c.text.split(' ');
      const mid = Math.ceil(words.length / 2);
      const line1 = words.slice(0, mid).join(' ');
      const line2 = words.slice(mid).join(' ');
      const text = line2 ? line1 + '\n' + line2 : line1;
      srt += c.idx + '\n' + c.start + ' --> ' + c.end + '\n' + text + '\n\n';
    }
    return srt.trim();
  })() }}

